from pathlib import Path

ROOT = Path(__file__).resolve().parent

def write_file(relative_path: str, content: str):
    path = ROOT / relative_path
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(content.strip() + '\n', encoding='utf-8')
    print(f'updated: {relative_path}')

def append_requirement(req: str):
    path = ROOT / 'backend' / 'requirements.txt'
    text = path.read_text(encoding='utf-8') if path.exists() else ''
    if req.lower() not in text.lower():
        path.write_text(text.rstrip() + '\n' + req + '\n', encoding='utf-8')
        print(f'updated: backend/requirements.txt -> added {req}')

append_requirement('lightgbm')

FILES = {
    'backend/app/ml_ranking_model.py': '\nimport json\nimport random\nfrom datetime import datetime\nfrom pathlib import Path\nfrom typing import Dict, Optional\n\nimport joblib\nimport pandas as pd\n\ntry:\n    from lightgbm import LGBMRanker\nexcept Exception:\n    LGBMRanker = None\n\nfrom sklearn.ensemble import RandomForestClassifier\nfrom sklearn.metrics import accuracy_score\n\nfrom .database import append_ml_training_rows, load_ml_training_rows\n\n\nDATA_DIR = Path(__file__).resolve().parents[2] / "data"\nMODEL_DIR = DATA_DIR / "models"\nMODEL_PATH = MODEL_DIR / "assignment_ranker.joblib"\nMETADATA_PATH = MODEL_DIR / "assignment_ranker_metadata.json"\n\nMODEL_OPTIONS = {\n    "lightgbm_ranker": "LightGBM LGBMRanker",\n    "random_forest": "RandomForestClassifier",\n    "random_baseline": "Random Baseline",\n}\n\nFEATURE_COLUMNS = [\n    "priority_value", "eligible", "base_score", "rag_bonus",\n    "deterministic_score", "skill_match", "availability", "workload",\n    "category_match", "past_performance", "experience", "speed",\n    "rejection_count",\n]\n\nPRIORITY_VALUE = {\n    "urgent": 4,\n    "high": 3,\n    "medium": 2,\n    "low": 1,\n}\n\n\ndef normalize_model_type(model_type: Optional[str]) -> str:\n    value = str(model_type or "lightgbm_ranker").lower().strip()\n\n    aliases = {\n        "light": "lightgbm_ranker",\n        "lgbm": "lightgbm_ranker",\n        "lightgbm": "lightgbm_ranker",\n        "ranker": "lightgbm_ranker",\n        "rf": "random_forest",\n        "randomforest": "random_forest",\n        "random_forest_classifier": "random_forest",\n        "random": "random_baseline",\n        "random_baseline": "random_baseline",\n        "baseline": "random_baseline",\n    }\n\n    return aliases.get(value, value if value in MODEL_OPTIONS else "lightgbm_ranker")\n\n\ndef _priority_value(priority: str) -> int:\n    return PRIORITY_VALUE.get(str(priority).lower(), 2)\n\n\ndef _safe_float(value, default=0.0) -> float:\n    try:\n        return float(value)\n    except (TypeError, ValueError):\n        return default\n\n\ndef _candidate_to_features(task: Dict, candidate: Dict) -> Dict:\n    breakdown = candidate.get("breakdown", {}) or {}\n\n    return {\n        "priority_value": _priority_value(task.get("priority")),\n        "eligible": 1 if candidate.get("eligible") else 0,\n        "base_score": _safe_float(candidate.get("base_score", candidate.get("final_score"))),\n        "rag_bonus": _safe_float(candidate.get("rag_bonus")),\n        "deterministic_score": _safe_float(candidate.get("base_rag_score", candidate.get("final_score"))),\n        "skill_match": _safe_float(breakdown.get("skill_match")),\n        "availability": _safe_float(breakdown.get("availability")),\n        "workload": _safe_float(breakdown.get("workload")),\n        "category_match": _safe_float(breakdown.get("category_match")),\n        "past_performance": _safe_float(breakdown.get("past_performance")),\n        "experience": _safe_float(breakdown.get("experience")),\n        "speed": _safe_float(breakdown.get("speed")),\n        "rejection_count": len(candidate.get("rejection_reasons", []) or []),\n    }\n\n\ndef append_candidate_training_rows(result: Dict) -> int:\n    if not result.get("assigned") or not result.get("assigned_resource"):\n        return 0\n\n    candidates = result.get("candidates", []) or []\n    if not candidates:\n        return 0\n\n    task = result.get("task", {}) or {}\n    assigned_resource_id = result.get("assigned_resource", {}).get("resource_id")\n    assigned_resource_name = result.get("assigned_resource", {}).get("name")\n\n    query_id = (\n        f"{datetime.now().strftime(\'%Y%m%d%H%M%S%f\')}|"\n        f"{task.get(\'title\', \'\')}|{task.get(\'category\', \'\')}|{task.get(\'priority\', \'\')}"\n    )\n\n    rows = []\n\n    for candidate in candidates:\n        features = _candidate_to_features(task, candidate)\n        label = int(\n            candidate.get("resource_id") == assigned_resource_id\n            or candidate.get("resource_name") == assigned_resource_name\n        )\n\n        rows.append({\n            "row_id": datetime.now().strftime("%Y%m%d%H%M%S%f") + str(len(rows)),\n            "query_id": query_id,\n            "timestamp": datetime.now().isoformat(timespec="seconds"),\n            "mode": result.get("mode", "normal_scoring"),\n            "task_title": task.get("title", ""),\n            "task_category": task.get("category", ""),\n            "task_priority": task.get("priority", ""),\n            "candidate_resource_id": candidate.get("resource_id", ""),\n            "candidate_resource_name": candidate.get("resource_name", ""),\n            **features,\n            "label_selected": label,\n        })\n\n    return append_ml_training_rows(rows)\n\n\ndef _load_training_frame() -> pd.DataFrame:\n    rows = load_ml_training_rows()\n    if not rows:\n        return pd.DataFrame()\n\n    df = pd.DataFrame(rows)\n\n    if "query_id" not in df.columns:\n        df["query_id"] = (\n            df.get("timestamp", "").astype(str) + "|"\n            + df.get("task_title", "").astype(str) + "|"\n            + df.get("task_category", "").astype(str) + "|"\n            + df.get("task_priority", "").astype(str)\n        )\n\n    df["label_selected"] = pd.to_numeric(df["label_selected"], errors="coerce").fillna(0).astype(int)\n\n    for column in FEATURE_COLUMNS:\n        if column not in df.columns:\n            df[column] = 0\n        df[column] = pd.to_numeric(df[column], errors="coerce").fillna(0)\n\n    df = df.sort_values(["query_id", "row_id"]).reset_index(drop=True)\n    return df\n\n\ndef _ranking_hit_at_1(df: pd.DataFrame, scores) -> float:\n    temp = df[["query_id", "label_selected"]].copy()\n    temp["score"] = scores\n\n    hits = 0\n    groups = 0\n\n    for _, group in temp.groupby("query_id", sort=False):\n        groups += 1\n        best = group.sort_values("score", ascending=False).iloc[0]\n        if int(best["label_selected"]) == 1:\n            hits += 1\n\n    return round(hits / max(groups, 1), 4)\n\n\ndef _group_sizes(df: pd.DataFrame) -> list:\n    return df.groupby("query_id", sort=False).size().astype(int).tolist()\n\n\ndef _read_metadata() -> Dict:\n    if METADATA_PATH.exists():\n        return json.loads(METADATA_PATH.read_text(encoding="utf-8"))\n    return {}\n\n\ndef get_ml_status() -> Dict:\n    df = _load_training_frame()\n    training_rows = len(df)\n    positive_rows = int((df["label_selected"] == 1).sum()) if training_rows else 0\n    negative_rows = training_rows - positive_rows\n    query_groups = int(df["query_id"].nunique()) if training_rows else 0\n    metadata = _read_metadata()\n\n    return {\n        "model_exists": MODEL_PATH.exists(),\n        "training_file_exists": training_rows > 0,\n        "training_rows": training_rows,\n        "positive_rows": positive_rows,\n        "negative_rows": negative_rows,\n        "query_groups": query_groups,\n        "model_path": str(MODEL_PATH),\n        "metadata": metadata,\n        "storage": "sqlite",\n        "available_model_types": [\n            {\n                "value": key,\n                "label": label,\n                "available": key != "lightgbm_ranker" or LGBMRanker is not None,\n            }\n            for key, label in MODEL_OPTIONS.items()\n        ],\n        "lightgbm_installed": LGBMRanker is not None,\n    }\n\n\ndef _validate_training_data(df: pd.DataFrame, model_type: str) -> Optional[str]:\n    if df.empty:\n        return "No candidate training data found yet. Run a few assignments first."\n\n    if len(df) < 4:\n        return "Not enough candidate rows yet. Run a few more assignments."\n\n    if df["label_selected"].nunique() < 2:\n        return "Training data needs both selected and non-selected candidates."\n\n    if model_type == "lightgbm_ranker" and int(df["query_id"].nunique()) < 2:\n        return "Training data needs at least 2 task groups for ranking."\n\n    return None\n\n\ndef _train_random_forest(df: pd.DataFrame) -> Dict:\n    X = df[FEATURE_COLUMNS].fillna(0)\n    y = df["label_selected"].astype(int)\n\n    model = RandomForestClassifier(\n        n_estimators=160,\n        max_depth=8,\n        random_state=42,\n        class_weight="balanced",\n    )\n    model.fit(X, y)\n\n    predictions = model.predict(X)\n    scores = model.predict_proba(X)[:, 1] if hasattr(model, "predict_proba") else predictions\n    train_accuracy = float(accuracy_score(y, predictions))\n    hit_at_1 = _ranking_hit_at_1(df, scores)\n\n    importances = sorted(\n        zip(FEATURE_COLUMNS, model.feature_importances_),\n        key=lambda item: item[1],\n        reverse=True,\n    )\n\n    return {\n        "model": model,\n        "model_type": "RandomForestClassifier",\n        "train_accuracy": round(train_accuracy, 4),\n        "train_hit_at_1": hit_at_1,\n        "top_features": [\n            {"feature": feature, "importance": round(float(value), 4)}\n            for feature, value in importances[:8]\n        ],\n    }\n\n\ndef _train_lgbm_ranker(df: pd.DataFrame) -> Dict:\n    X = df[FEATURE_COLUMNS].fillna(0)\n    y = df["label_selected"].astype(int)\n    groups = _group_sizes(df)\n\n    model = LGBMRanker(\n        objective="lambdarank",\n        metric="ndcg",\n        n_estimators=180,\n        learning_rate=0.05,\n        num_leaves=15,\n        max_depth=-1,\n        random_state=42,\n        verbose=-1,\n    )\n\n    model.fit(X, y, group=groups)\n\n    scores = model.predict(X)\n    hit_at_1 = _ranking_hit_at_1(df, scores)\n\n    importances = sorted(\n        zip(FEATURE_COLUMNS, model.feature_importances_),\n        key=lambda item: item[1],\n        reverse=True,\n    )\n\n    return {\n        "model": model,\n        "model_type": "LightGBM LGBMRanker",\n        "train_accuracy": None,\n        "train_hit_at_1": hit_at_1,\n        "top_features": [\n            {"feature": feature, "importance": round(float(value), 4)}\n            for feature, value in importances[:8]\n        ],\n    }\n\n\ndef _train_random_baseline(df: pd.DataFrame) -> Dict:\n    random.seed(42)\n    scores = [random.random() for _ in range(len(df))]\n    hit_at_1 = _ranking_hit_at_1(df, scores)\n\n    return {\n        "model": {\n            "kind": "random_baseline",\n            "seed": 42,\n        },\n        "model_type": "Random Baseline",\n        "train_accuracy": None,\n        "train_hit_at_1": hit_at_1,\n        "top_features": [],\n    }\n\n\ndef train_ml_model(model_type: Optional[str] = None) -> Dict:\n    selected_model_type = normalize_model_type(model_type)\n    df = _load_training_frame()\n\n    validation_error = _validate_training_data(df, selected_model_type)\n    if validation_error:\n        return {\n            "trained": False,\n            "message": validation_error,\n            "status": get_ml_status(),\n        }\n\n    if selected_model_type == "lightgbm_ranker":\n        if LGBMRanker is None:\n            return {\n                "trained": False,\n                "message": "LightGBM is not installed. Run: pip install lightgbm",\n                "status": get_ml_status(),\n            }\n        train_result = _train_lgbm_ranker(df)\n    elif selected_model_type == "random_forest":\n        train_result = _train_random_forest(df)\n    else:\n        train_result = _train_random_baseline(df)\n\n    MODEL_DIR.mkdir(parents=True, exist_ok=True)\n    joblib.dump({\n        "model": train_result["model"],\n        "model_type": train_result["model_type"],\n        "requested_model_type": selected_model_type,\n        "feature_columns": FEATURE_COLUMNS,\n    }, MODEL_PATH)\n\n    metadata = {\n        "trained_at": datetime.now().isoformat(timespec="seconds"),\n        "training_rows": int(len(df)),\n        "query_groups": int(df["query_id"].nunique()),\n        "positive_rows": int((df["label_selected"] == 1).sum()),\n        "negative_rows": int((df["label_selected"] == 0).sum()),\n        "requested_model_type": selected_model_type,\n        "model_type": train_result["model_type"],\n        "train_accuracy": train_result["train_accuracy"],\n        "train_hit_at_1": train_result["train_hit_at_1"],\n        "storage": "sqlite",\n        "top_features": train_result["top_features"],\n    }\n\n    METADATA_PATH.write_text(json.dumps(metadata, indent=2), encoding="utf-8")\n\n    return {\n        "trained": True,\n        "message": f"{train_result[\'model_type\']} trained successfully.",\n        "metadata": metadata,\n        "status": get_ml_status(),\n    }\n\n\ndef _load_model_bundle():\n    if not MODEL_PATH.exists():\n        return None\n\n    loaded = joblib.load(MODEL_PATH)\n\n    if isinstance(loaded, dict) and "model" in loaded:\n        return loaded\n\n    return {\n        "model": loaded,\n        "model_type": "LegacyModel",\n        "requested_model_type": "legacy",\n        "feature_columns": FEATURE_COLUMNS,\n    }\n\n\ndef _predict_candidate_score(model_bundle: Dict, task: Dict, candidate: Dict) -> float:\n    model = model_bundle["model"]\n    model_type = model_bundle.get("model_type", "")\n    feature_columns = model_bundle.get("feature_columns", FEATURE_COLUMNS)\n\n    if model_type == "Random Baseline" or isinstance(model, dict) and model.get("kind") == "random_baseline":\n        key = f"{task.get(\'title\', \'\')}|{candidate.get(\'resource_id\', \'\')}|{candidate.get(\'resource_name\', \'\')}"\n        return random.Random(key).random()\n\n    features = _candidate_to_features(task, candidate)\n    X = pd.DataFrame([{column: features.get(column, 0) for column in feature_columns}])\n\n    if "Ranker" in model_type or hasattr(model, "booster_"):\n        return float(model.predict(X)[0])\n\n    if hasattr(model, "predict_proba"):\n        return float(model.predict_proba(X)[0][1])\n\n    return float(model.predict(X)[0])\n\n\ndef _append_ml_workflow_step(result: Dict, model_available: bool, winner: Optional[Dict], model_type: str = "") -> None:\n    trace = result.get("workflow_trace") or []\n\n    trace.append({\n        "name": "ML Ranker",\n        "status": "completed" if model_available else "fallback",\n        "detail": (\n            f"{model_type} re-ranked eligible candidates using candidate-level training history from SQLite."\n            if model_available\n            else "No trained ML model found, so the system used Agentic RAG scoring as fallback."\n        ),\n        "data": {\n            "model_available": model_available,\n            "model_type": model_type,\n            "selected_by_ml": winner.get("resource_name") if winner else None,\n            "ml_score": winner.get("ml_score") if winner else None,\n        },\n    })\n\n    result["workflow_trace"] = trace\n\n\ndef assign_task_ml(task: Dict, now_hhmm: Optional[str] = None, model_type: Optional[str] = None) -> Dict:\n    from .agentic_assignment_engine import assign_task_agentic\n\n    result = assign_task_agentic(task, now_hhmm=now_hhmm)\n    model_bundle = _load_model_bundle()\n\n    if model_bundle is None or not result.get("assigned"):\n        result["mode"] = "ml_ranker_fallback"\n        result["explanation"] = (\n            result.get("explanation", "")\n            + " ML ranker fallback was used because no trained model is available yet."\n        ).strip()\n        _append_ml_workflow_step(result, False, None)\n        return result\n\n    requested = normalize_model_type(model_type)\n    trained_requested = model_bundle.get("requested_model_type")\n\n    if model_type and trained_requested and requested != trained_requested:\n        # Runtime uses the currently trained model file. Frontend should train selected type first.\n        result["model_warning"] = (\n            f"Requested {requested}, but currently trained model is {trained_requested}. "\n            f"Train {requested} first to switch."\n        )\n\n    task_data = result.get("task", {}) or {}\n    candidates = result.get("candidates", []) or []\n    actual_model_type = model_bundle.get("model_type", "MLRanker")\n\n    raw_scores = []\n\n    for candidate in candidates:\n        candidate["base_rag_score"] = candidate.get("final_score", 0)\n\n        if candidate.get("eligible"):\n            raw_score = _predict_candidate_score(model_bundle, task_data, candidate)\n            candidate["ml_raw_score"] = round(raw_score, 4)\n            raw_scores.append(raw_score)\n        else:\n            candidate["ml_raw_score"] = 0.0\n\n    eligible_raw_scores = [candidate["ml_raw_score"] for candidate in candidates if candidate.get("eligible")]\n    min_score = min(eligible_raw_scores) if eligible_raw_scores else 0\n    max_score = max(eligible_raw_scores) if eligible_raw_scores else 1\n    score_range = max(max_score - min_score, 1e-9)\n\n    for candidate in candidates:\n        if candidate.get("eligible"):\n            normalized_score = (candidate["ml_raw_score"] - min_score) / score_range\n            candidate["ml_probability"] = round(normalized_score, 4)\n            candidate["ml_score"] = round((normalized_score * 100 * 0.65) + (candidate["base_rag_score"] * 0.35), 2)\n            candidate["final_score"] = candidate["ml_score"]\n            candidate["positive_reasons"] = candidate.get("positive_reasons", []) + [\n                f"{actual_model_type} normalized rank score {round(normalized_score * 100, 2)}%"\n            ]\n        else:\n            candidate["ml_probability"] = 0.0\n            candidate["ml_score"] = 0.0\n\n    candidates.sort(key=lambda item: item.get("final_score", 0), reverse=True)\n    valid_candidates = [candidate for candidate in candidates if candidate.get("eligible")]\n\n    if not valid_candidates:\n        result["mode"] = "ml_ranker"\n        result["assigned"] = False\n        result["assigned_resource"] = None\n        _append_ml_workflow_step(result, True, None, model_type=actual_model_type)\n        return result\n\n    winner = valid_candidates[0]\n\n    result["mode"] = "ml_ranker"\n    result["candidates"] = candidates\n    result["assigned"] = True\n    result["assigned_resource"] = {\n        "resource_id": winner["resource_id"],\n        "name": winner["resource_name"],\n        "score": winner["final_score"],\n        "base_score": winner.get("base_score"),\n        "rag_bonus": winner.get("rag_bonus"),\n        "ml_probability": winner.get("ml_probability"),\n        "ml_score": winner.get("ml_score"),\n        "ml_raw_score": winner.get("ml_raw_score"),\n        "model_type": actual_model_type,\n    }\n\n    warning_text = f" Warning: {result.get(\'model_warning\')}" if result.get("model_warning") else ""\n\n    result["explanation"] = (\n        f"{actual_model_type} assigned this task to {winner.get(\'resource_name\')} after using "\n        f"Agentic RAG evidence plus the selected ML model. "\n        f"The selected candidate received normalized ML rank score "\n        f"{round(winner.get(\'ml_probability\', 0) * 100, 2)}% and blended score "\n        f"{winner.get(\'ml_score\')}. "\n        f"{warning_text} "\n        f"Original explanation: {result.get(\'explanation\', \'\')}"\n    )\n\n    _append_ml_workflow_step(result, True, winner, model_type=actual_model_type)\n    return result\n',
    'backend/app/main.py': '\nfrom typing import Optional\n\nfrom fastapi import FastAPI, HTTPException, Query\nfrom fastapi.middleware.cors import CORSMiddleware\n\nfrom .agentic_assignment_engine import assign_task_agentic\nfrom .analytics_engine import build_analytics_summary\nfrom .assignment_engine import assign_single_task, assign_tasks\nfrom .database import (\n    append_assignment_log,\n    get_db_status,\n    load_assignment_logs,\n    load_history,\n    load_resources,\n    load_tasks,\n    save_resources,\n)\nfrom .llm_provider import get_llm_status\nfrom .ml_ranking_model import (\n    append_candidate_training_rows,\n    assign_task_ml,\n    get_ml_status,\n    train_ml_model,\n)\nfrom .mock_generator import generate_mock_resource, generate_mock_task\nfrom .schemas import AssignmentRequest, ResourceIn, TaskIn\n\n\napp = FastAPI(\n    title="AI Task Allocation System",\n    description="Smart workforce task allocation using deterministic scoring, Agentic RAG, workflow traces, assignment history, selectable ML models, analytics, SQLite persistence, and multi-provider LLM support.",\n    version="1.8.0",\n)\n\napp.add_middleware(\n    CORSMiddleware,\n    allow_origins=["*"],\n    allow_credentials=True,\n    allow_methods=["*"],\n    allow_headers=["*"],\n)\n\n\ndef _next_resource_id(resources):\n    used_numbers = []\n    for resource in resources:\n        rid = str(resource.get("resource_id", "")).upper().replace("R", "")\n        if rid.isdigit():\n            used_numbers.append(int(rid))\n    return f"R{max(used_numbers, default=0) + 1}"\n\n\ndef _log_result(result):\n    append_assignment_log(result)\n    append_candidate_training_rows(result)\n\n\n@app.get("/")\ndef health_check():\n    return {\n        "status": "ok",\n        "app": "AI Task Allocation System",\n        "message": "Backend is running. Open /docs for API testing.",\n    }\n\n\n@app.get("/db/status")\ndef db_status():\n    return get_db_status()\n\n\n@app.get("/llm/status")\ndef llm_status():\n    return get_llm_status()\n\n\n@app.post("/mock/task")\ndef mock_task(provider: Optional[str] = Query(default=None)):\n    return generate_mock_task(provider=provider)\n\n\n@app.post("/mock/resource")\ndef mock_resource(provider: Optional[str] = Query(default=None)):\n    return generate_mock_resource(provider=provider)\n\n\n@app.get("/analytics/summary")\ndef analytics_summary(limit: int = Query(default=500, ge=1, le=2000)):\n    return build_analytics_summary(limit=limit)\n\n\n@app.get("/resources")\ndef get_resources():\n    return load_resources()\n\n\n@app.post("/resources")\ndef create_resource(resource: ResourceIn):\n    resources = load_resources()\n    data = resource.model_dump()\n\n    if not data["resource_id"]:\n        data["resource_id"] = _next_resource_id(resources)\n\n    if any(item["resource_id"] == data["resource_id"] for item in resources):\n        raise HTTPException(status_code=409, detail="Resource ID already exists.")\n\n    data["skills"] = [skill.strip().lower() for skill in data["skills"] if skill.strip()]\n    data["handled_categories"] = [\n        category.strip().lower()\n        for category in data["handled_categories"]\n        if category.strip()\n    ]\n    data["status"] = data["status"].lower()\n\n    resources.append(data)\n    save_resources(resources)\n\n    return {\n        "message": "Resource created successfully.",\n        "resource": data,\n    }\n\n\n@app.put("/resources/{resource_id}")\ndef update_resource(resource_id: str, resource: ResourceIn):\n    resources = load_resources()\n    data = resource.model_dump()\n    data["resource_id"] = resource_id\n    data["skills"] = [skill.strip().lower() for skill in data["skills"] if skill.strip()]\n    data["handled_categories"] = [\n        category.strip().lower()\n        for category in data["handled_categories"]\n        if category.strip()\n    ]\n    data["status"] = data["status"].lower()\n\n    for index, existing in enumerate(resources):\n        if existing["resource_id"] == resource_id:\n            resources[index] = data\n            save_resources(resources)\n            return {\n                "message": "Resource updated successfully.",\n                "resource": data,\n            }\n\n    raise HTTPException(status_code=404, detail="Resource not found.")\n\n\n@app.delete("/resources/{resource_id}")\ndef delete_resource(resource_id: str):\n    resources = load_resources()\n    remaining = [resource for resource in resources if resource["resource_id"] != resource_id]\n\n    if len(remaining) == len(resources):\n        raise HTTPException(status_code=404, detail="Resource not found.")\n\n    save_resources(remaining)\n\n    return {\n        "message": "Resource deleted successfully.",\n        "resource_id": resource_id,\n    }\n\n\n@app.get("/tasks")\ndef get_tasks():\n    return load_tasks()\n\n\n@app.get("/history")\ndef get_history():\n    return load_history()\n\n\n@app.get("/assignment-logs")\ndef get_assignment_logs(limit: int = Query(default=50, ge=1, le=500)):\n    return load_assignment_logs(limit=limit)\n\n\n@app.get("/ml/status")\ndef ml_status():\n    return get_ml_status()\n\n\n@app.post("/ml/train")\ndef ml_train(model_type: Optional[str] = Query(default="lightgbm_ranker")):\n    return train_ml_model(model_type=model_type)\n\n\n@app.post("/assign")\ndef assign_task(task: TaskIn, now_hhmm: Optional[str] = Query(default=None)):\n    result = assign_single_task(task.model_dump(), now_hhmm=now_hhmm)\n    _log_result(result)\n    return result\n\n\n@app.post("/assign/agentic")\ndef assign_task_with_agentic_rag(task: TaskIn, now_hhmm: Optional[str] = Query(default=None)):\n    result = assign_task_agentic(task.model_dump(), now_hhmm=now_hhmm)\n    _log_result(result)\n    return result\n\n\n@app.post("/assign/ml")\ndef assign_task_with_ml_ranker(\n    task: TaskIn,\n    now_hhmm: Optional[str] = Query(default=None),\n    model_type: Optional[str] = Query(default=None),\n):\n    result = assign_task_ml(task.model_dump(), now_hhmm=now_hhmm, model_type=model_type)\n    _log_result(result)\n    return result\n\n\n@app.post("/assign/batch")\ndef assign_batch(payload: AssignmentRequest):\n    result = assign_tasks(\n        [task.model_dump() for task in payload.tasks],\n        now_hhmm=payload.now_hhmm,\n    )\n\n    for item in result.get("assignments", []):\n        _log_result(item)\n\n    return result\n\n\n@app.post("/assign/sample")\ndef assign_sample(now_hhmm: Optional[str] = Query(default="10:30")):\n    result = assign_tasks(load_tasks(), now_hhmm=now_hhmm)\n\n    for item in result.get("assignments", []):\n        _log_result(item)\n\n    return result\n',
    'frontend/src/components/MLPanel.jsx': '\nexport default function MLPanel({ status, selectedModelType, onModelTypeChange, onTrain, loading }) {\n  const metadata = status?.metadata || {};\n  const topFeatures = metadata.top_features || [];\n  const options = status?.available_model_types || [\n    { value: "lightgbm_ranker", label: "LightGBM LGBMRanker", available: true },\n    { value: "random_forest", label: "RandomForestClassifier", available: true },\n    { value: "random_baseline", label: "Random Baseline", available: true },\n  ];\n\n  return (\n    <div className="card">\n      <h2>Trainable ML Ranker</h2>\n      <p className="muted">\n        Choose which ML strategy to train/use. LightGBM Ranker is best for this task-allocation ranking problem.\n      </p>\n\n      <div className="modelSelector">\n        <label>\n          ML strategy\n          <select\n            value={selectedModelType}\n            onChange={(event) => onModelTypeChange(event.target.value)}\n          >\n            {options.map((option) => (\n              <option key={option.value} value={option.value} disabled={!option.available}>\n                {option.label}{option.available ? "" : " (install dependency)"}\n              </option>\n            ))}\n          </select>\n        </label>\n      </div>\n\n      <div className="mlGrid">\n        <div>\n          <b>{status?.model_exists ? "Ready" : "Not trained"}</b>\n          <span>Model status</span>\n        </div>\n        <div>\n          <b>{metadata.model_type || "Not trained yet"}</b>\n          <span>Current trained model</span>\n        </div>\n        <div>\n          <b>{status?.training_rows || 0}</b>\n          <span>Candidate rows</span>\n        </div>\n        <div>\n          <b>{status?.query_groups || metadata.query_groups || 0}</b>\n          <span>Task groups</span>\n        </div>\n        <div>\n          <b>{status?.positive_rows || 0}</b>\n          <span>Selected rows</span>\n        </div>\n        <div>\n          <b>{status?.negative_rows || 0}</b>\n          <span>Rejected rows</span>\n        </div>\n        <div>\n          <b>{metadata.train_hit_at_1 ?? "-"}</b>\n          <span>Train Hit@1</span>\n        </div>\n        <div>\n          <b>{status?.lightgbm_installed ? "Yes" : "No"}</b>\n          <span>LightGBM installed</span>\n        </div>\n      </div>\n\n      {metadata.trained_at && (\n        <div className="mlMeta">\n          <strong>Last trained</strong>\n          <span>{metadata.trained_at}</span>\n          <strong>Selected strategy</strong>\n          <span>{selectedModelType}</span>\n          <strong>Saved model type</strong>\n          <span>{metadata.model_type}</span>\n          <strong>Ranking metric</strong>\n          <span>Hit@1 = {metadata.train_hit_at_1 ?? "-"}</span>\n        </div>\n      )}\n\n      {topFeatures.length > 0 && (\n        <div className="featureList">\n          <strong>Top learned features</strong>\n          {topFeatures.map((item) => (\n            <div key={item.feature}>\n              <span>{item.feature.replaceAll("_", " ")}</span>\n              <b>{item.importance}</b>\n            </div>\n          ))}\n        </div>\n      )}\n\n      <button onClick={() => onTrain(selectedModelType)} disabled={loading}>\n        {loading ? "Training..." : `Train ${selectedModelType.replaceAll("_", " ")}`}\n      </button>\n    </div>\n  );\n}\n',
    'frontend/src/components/TaskForm.jsx': '\nimport { useState } from "react";\n\nconst DEFAULT_TASK = {\n  title: "Customer payment failed",\n  description: "Customer says payment failed after checkout using card",\n  priority: "high",\n  category: "payment",\n  required_skills: "payments,billing,customer_support",\n  sla_minutes: 60,\n};\n\nexport default function TaskForm({\n  onAssign,\n  onAgenticAssign,\n  onMlAssign,\n  onGenerateMockTask,\n  selectedModelType,\n  loading,\n  agenticLoading,\n  mlLoading,\n  mockTaskLoading,\n}) {\n  const [task, setTask] = useState(DEFAULT_TASK);\n\n  function updateField(field, value) {\n    setTask((current) => ({\n      ...current,\n      [field]: value,\n    }));\n  }\n\n  async function fillMockTask() {\n    const mock = await onGenerateMockTask();\n    if (!mock) return;\n\n    setTask({\n      title: mock.title || "",\n      description: mock.description || "",\n      priority: mock.priority || "medium",\n      category: mock.category || "general",\n      required_skills: Array.isArray(mock.required_skills)\n        ? mock.required_skills.join(",")\n        : String(mock.required_skills || ""),\n      sla_minutes: mock.sla_minutes || 120,\n    });\n  }\n\n  function buildPayload() {\n    return {\n      task_id: `CUSTOM-${Date.now()}`,\n      title: task.title.trim(),\n      description: task.description.trim(),\n      priority: task.priority,\n      category: task.category.trim() || null,\n      required_skills: task.required_skills\n        .split(",")\n        .map((skill) => skill.trim().toLowerCase())\n        .filter(Boolean),\n      sla_minutes: Number(task.sla_minutes) || 120,\n    };\n  }\n\n  function submitTask(event) {\n    event.preventDefault();\n    onAssign(buildPayload());\n  }\n\n  function submitAgenticTask() {\n    onAgenticAssign(buildPayload());\n  }\n\n  function submitMlTask() {\n    onMlAssign(buildPayload(), selectedModelType);\n  }\n\n  const disabled = loading || agenticLoading || mlLoading || mockTaskLoading;\n\n  return (\n    <div className="card">\n      <div className="formHeader">\n        <div>\n          <h2>Assign a Custom Task</h2>\n          <p className="muted">\n            Normal uses scoring. Agentic RAG retrieves evidence. ML assignment uses the selected ML strategy.\n          </p>\n        </div>\n\n        <button\n          type="button"\n          className="mockButton"\n          disabled={disabled}\n          onClick={fillMockTask}\n        >\n          {mockTaskLoading ? "Generating..." : "Generate Mock Task"}\n        </button>\n      </div>\n\n      <form className="taskForm" onSubmit={submitTask}>\n        <label>\n          Task title\n          <input\n            value={task.title}\n            onChange={(event) => updateField("title", event.target.value)}\n            placeholder="Example: Customer payment failed"\n            required\n          />\n        </label>\n\n        <label>\n          Description\n          <textarea\n            value={task.description}\n            onChange={(event) => updateField("description", event.target.value)}\n            placeholder="Describe what happened..."\n            rows={4}\n          />\n        </label>\n\n        <div className="formGrid">\n          <label>\n            Priority\n            <select\n              value={task.priority}\n              onChange={(event) => updateField("priority", event.target.value)}\n            >\n              <option value="urgent">urgent</option>\n              <option value="high">high</option>\n              <option value="medium">medium</option>\n              <option value="low">low</option>\n            </select>\n          </label>\n\n          <label>\n            Category\n            <input\n              value={task.category}\n              onChange={(event) => updateField("category", event.target.value)}\n              placeholder="payment, technical, billing..."\n            />\n          </label>\n\n          <label>\n            SLA minutes\n            <input\n              type="number"\n              value={task.sla_minutes}\n              onChange={(event) => updateField("sla_minutes", event.target.value)}\n              min="1"\n            />\n          </label>\n        </div>\n\n        <label>\n          Required skills\n          <input\n            value={task.required_skills}\n            onChange={(event) => updateField("required_skills", event.target.value)}\n            placeholder="payments,billing,customer_support"\n          />\n          <small>Use comma-separated skills.</small>\n        </label>\n\n        <div className="buttonRow three">\n          <button type="submit" disabled={disabled}>\n            {loading ? "Finding..." : "Normal Assignment"}\n          </button>\n\n          <button\n            type="button"\n            className="secondaryButton"\n            disabled={disabled}\n            onClick={submitAgenticTask}\n          >\n            {agenticLoading ? "Running RAG..." : "Agentic RAG Assignment"}\n          </button>\n\n          <button\n            type="button"\n            className="mlButton"\n            disabled={disabled}\n            onClick={submitMlTask}\n          >\n            {mlLoading ? "Running ML..." : `ML Assignment (${selectedModelType.replaceAll("_", " ")})`}\n          </button>\n        </div>\n      </form>\n    </div>\n  );\n}\n',
    'frontend/src/App.jsx': '\nimport { useEffect, useState } from "react";\n\nimport { apiDelete, apiGet, apiPost } from "./api/client";\nimport AssignmentCard from "./components/AssignmentCard";\nimport AssignmentHistory from "./components/AssignmentHistory";\nimport Dashboard from "./components/Dashboard";\nimport LLMPanel from "./components/LLMPanel";\nimport MLPanel from "./components/MLPanel";\nimport ResourceForm from "./components/ResourceForm";\nimport ResourceTable from "./components/ResourceTable";\nimport TaskForm from "./components/TaskForm";\nimport TaskTable from "./components/TaskTable";\n\nfunction SingleAssignmentResult({ result }) {\n  if (!result) return null;\n\n  const title =\n    result.mode === "agentic_rag"\n      ? "Agentic RAG Assignment Result"\n      : result.mode === "ml_ranker" || result.mode === "ml_ranker_fallback"\n        ? "ML Strategy Assignment Result"\n        : "Custom Task Assignment Result";\n\n  return (\n    <div className="card">\n      <h2>{title}</h2>\n      <AssignmentCard item={result} />\n    </div>\n  );\n}\n\nfunction BatchAssignmentResult({ result }) {\n  if (!result) return null;\n\n  return (\n    <div className="card">\n      <h2>Sample Batch Assignment Result</h2>\n      <p>\n        Assigned {result.assigned_count} of {result.total_tasks} tasks.\n        Unassigned: {result.unassigned_count}.\n      </p>\n\n      <div className="results">\n        {result.assignments.map((item) => (\n          <AssignmentCard key={item.task.task_id} item={item} />\n        ))}\n      </div>\n    </div>\n  );\n}\n\nexport default function App() {\n  const [resources, setResources] = useState([]);\n  const [tasks, setTasks] = useState([]);\n  const [assignmentLogs, setAssignmentLogs] = useState([]);\n  const [mlStatus, setMlStatus] = useState(null);\n  const [llmStatus, setLlmStatus] = useState(null);\n  const [analytics, setAnalytics] = useState(null);\n  const [selectedModelType, setSelectedModelType] = useState("lightgbm_ranker");\n  const [batchResult, setBatchResult] = useState(null);\n  const [singleResult, setSingleResult] = useState(null);\n  const [now, setNow] = useState("10:30");\n  const [loadingBatch, setLoadingBatch] = useState(false);\n  const [loadingSingle, setLoadingSingle] = useState(false);\n  const [loadingAgentic, setLoadingAgentic] = useState(false);\n  const [loadingMl, setLoadingMl] = useState(false);\n  const [loadingTrain, setLoadingTrain] = useState(false);\n  const [loadingResource, setLoadingResource] = useState(false);\n  const [loadingMockTask, setLoadingMockTask] = useState(false);\n  const [loadingMockResource, setLoadingMockResource] = useState(false);\n  const [error, setError] = useState("");\n\n  async function loadData() {\n    try {\n      const [resourceData, taskData, logsData, mlData, analyticsData, llmData] = await Promise.all([\n        apiGet("/resources"),\n        apiGet("/tasks"),\n        apiGet("/assignment-logs"),\n        apiGet("/ml/status"),\n        apiGet("/analytics/summary"),\n        apiGet("/llm/status"),\n      ]);\n\n      setResources(resourceData);\n      setTasks(taskData);\n      setAssignmentLogs(logsData);\n      setMlStatus(mlData);\n      setAnalytics(analyticsData);\n      setLlmStatus(llmData);\n\n      const trainedType = mlData?.metadata?.requested_model_type;\n      if (trainedType) {\n        setSelectedModelType(trainedType);\n      }\n    } catch (err) {\n      setError(err.message);\n    }\n  }\n\n  async function refreshRuntimeData() {\n    try {\n      const [logsData, mlData, analyticsData, llmData] = await Promise.all([\n        apiGet("/assignment-logs"),\n        apiGet("/ml/status"),\n        apiGet("/analytics/summary"),\n        apiGet("/llm/status"),\n      ]);\n      setAssignmentLogs(logsData);\n      setMlStatus(mlData);\n      setAnalytics(analyticsData);\n      setLlmStatus(llmData);\n    } catch (err) {\n      setError(err.message);\n    }\n  }\n\n  async function generateMockTask() {\n    setLoadingMockTask(true);\n    setError("");\n\n    try {\n      const data = await apiPost("/mock/task?provider=ollama");\n      if (!data.llm_used && data.fallback_reason) {\n        setError(`Mock task used fallback: ${data.fallback_reason}`);\n      }\n      return data;\n    } catch (err) {\n      setError(err.message);\n      return null;\n    } finally {\n      setLoadingMockTask(false);\n    }\n  }\n\n  async function generateMockResource() {\n    setLoadingMockResource(true);\n    setError("");\n\n    try {\n      const data = await apiPost("/mock/resource?provider=ollama");\n      if (!data.llm_used && data.fallback_reason) {\n        setError(`Mock resource used fallback: ${data.fallback_reason}`);\n      }\n      return data;\n    } catch (err) {\n      setError(err.message);\n      return null;\n    } finally {\n      setLoadingMockResource(false);\n    }\n  }\n\n  async function trainMlRanker(modelType) {\n    setLoadingTrain(true);\n    setError("");\n\n    try {\n      const data = await apiPost(`/ml/train?model_type=${encodeURIComponent(modelType)}`);\n      setMlStatus(data.status || data);\n      await refreshRuntimeData();\n      if (!data.trained) {\n        setError(data.message);\n      }\n    } catch (err) {\n      setError(err.message);\n    } finally {\n      setLoadingTrain(false);\n    }\n  }\n\n  async function createResource(payload) {\n    setLoadingResource(true);\n    setError("");\n\n    try {\n      await apiPost("/resources", payload);\n      await loadData();\n    } catch (err) {\n      setError(err.message);\n    } finally {\n      setLoadingResource(false);\n    }\n  }\n\n  async function deleteResource(resourceId) {\n    const confirmed = window.confirm("Delete this resource?");\n    if (!confirmed) return;\n\n    setError("");\n\n    try {\n      await apiDelete(`/resources/${resourceId}`);\n      await loadData();\n    } catch (err) {\n      setError(err.message);\n    }\n  }\n\n  async function runSampleAssignment() {\n    setLoadingBatch(true);\n    setError("");\n\n    try {\n      const data = await apiPost(`/assign/sample?now_hhmm=${encodeURIComponent(now)}`);\n      setBatchResult(data);\n      await refreshRuntimeData();\n    } catch (err) {\n      setError(err.message);\n    } finally {\n      setLoadingBatch(false);\n    }\n  }\n\n  async function runCustomAssignment(taskPayload) {\n    setLoadingSingle(true);\n    setError("");\n\n    try {\n      const data = await apiPost(`/assign?now_hhmm=${encodeURIComponent(now)}`, taskPayload);\n      setSingleResult(data);\n      await refreshRuntimeData();\n    } catch (err) {\n      setError(err.message);\n    } finally {\n      setLoadingSingle(false);\n    }\n  }\n\n  async function runAgenticAssignment(taskPayload) {\n    setLoadingAgentic(true);\n    setError("");\n\n    try {\n      const data = await apiPost(`/assign/agentic?now_hhmm=${encodeURIComponent(now)}`, taskPayload);\n      setSingleResult(data);\n      await refreshRuntimeData();\n    } catch (err) {\n      setError(err.message);\n    } finally {\n      setLoadingAgentic(false);\n    }\n  }\n\n  async function runMlAssignment(taskPayload, modelType) {\n    setLoadingMl(true);\n    setError("");\n\n    try {\n      const data = await apiPost(\n        `/assign/ml?now_hhmm=${encodeURIComponent(now)}&model_type=${encodeURIComponent(modelType)}`,\n        taskPayload\n      );\n      setSingleResult(data);\n      await refreshRuntimeData();\n    } catch (err) {\n      setError(err.message);\n    } finally {\n      setLoadingMl(false);\n    }\n  }\n\n  useEffect(() => {\n    loadData();\n  }, []);\n\n  return (\n    <main className="app">\n      <section className="hero">\n        <div>\n          <h1>AI Task Allocation System</h1>\n          <p>\n            Assign service/support tasks using deterministic scoring, Agentic RAG retrieval,\n            workflow traces, assignment history, selectable ML models, SQLite, analytics, and optional LLM providers.\n          </p>\n        </div>\n\n        <div className="controls">\n          <label>\n            Demo time{" "}\n            <input value={now} onChange={(event) => setNow(event.target.value)} />\n          </label>\n          <button onClick={runSampleAssignment} disabled={loadingBatch}>\n            {loadingBatch ? "Assigning..." : "Run Sample Batch"}\n          </button>\n        </div>\n      </section>\n\n      {error && <div className="error">{error}</div>}\n\n      <section className="grid">\n        <Dashboard analytics={analytics} />\n        <LLMPanel status={llmStatus} />\n\n        <TaskForm\n          onAssign={runCustomAssignment}\n          onAgenticAssign={runAgenticAssignment}\n          onMlAssign={runMlAssignment}\n          onGenerateMockTask={generateMockTask}\n          selectedModelType={selectedModelType}\n          loading={loadingSingle}\n          agenticLoading={loadingAgentic}\n          mlLoading={loadingMl}\n          mockTaskLoading={loadingMockTask}\n        />\n\n        <SingleAssignmentResult result={singleResult} />\n\n        <MLPanel\n          status={mlStatus}\n          selectedModelType={selectedModelType}\n          onModelTypeChange={setSelectedModelType}\n          onTrain={trainMlRanker}\n          loading={loadingTrain}\n        />\n\n        <AssignmentHistory logs={assignmentLogs} />\n\n        <ResourceForm\n          onCreate={createResource}\n          onGenerateMockResource={generateMockResource}\n          loading={loadingResource}\n          mockResourceLoading={loadingMockResource}\n        />\n        <ResourceTable resources={resources} onDelete={deleteResource} />\n\n        <TaskTable tasks={tasks} />\n\n        <BatchAssignmentResult result={batchResult} />\n      </section>\n    </main>\n  );\n}\n',
}

for path, content in FILES.items():
    write_file(path, content)

css_path = ROOT / 'frontend/src/styles.css'
